-- PostgreSQL CREATE TABLE statements

DROP TABLE IF EXISTS "wishlist" CASCADE;
DROP TABLE IF EXISTS "reviews" CASCADE;
DROP TABLE IF EXISTS "order_items" CASCADE;
DROP TABLE IF EXISTS "orders" CASCADE;
DROP TABLE IF EXISTS "products" CASCADE;
DROP TABLE IF EXISTS "customers" CASCADE;
DROP TABLE IF EXISTS "categories" CASCADE;

CREATE TABLE "categories" (
  "id" SERIAL PRIMARY KEY,
  "name" TEXT NOT NULL,
  "parent_category_id" INTEGER,
  "description" TEXT,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("parent_category_id") REFERENCES "categories" ("id")
);

CREATE TABLE "customers" (
  "id" SERIAL PRIMARY KEY,
  "first_name" TEXT NOT NULL,
  "last_name" TEXT NOT NULL,
  "email" TEXT NOT NULL UNIQUE,
  "phone" TEXT,
  "date_of_birth" DATE,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "products" (
  "id" SERIAL PRIMARY KEY,
  "name" TEXT NOT NULL,
  "description" TEXT,
  "sku" TEXT NOT NULL UNIQUE,
  "category_id" INTEGER NOT NULL,
  "brand" TEXT NOT NULL,
  "price" NUMERIC(10,2) NOT NULL,
  "weight_kg" NUMERIC(10,2),
  "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("category_id") REFERENCES "categories" ("id")
);

CREATE TABLE "orders" (
  "id" SERIAL PRIMARY KEY,
  "customer_id" INTEGER,
  "status" TEXT,
  "subtotal" NUMERIC(10,2),
  "tax_amount" NUMERIC(10,2),
  "shipping_amount" NUMERIC(10,2),
  "total_amount" NUMERIC(10,2),
  "order_date" TIMESTAMP,
  "shipped_date" TIMESTAMP,
  "delivered_date" TIMESTAMP,
  "created_at" TIMESTAMP,
  "updated_at" TIMESTAMP,
  FOREIGN KEY ("customer_id") REFERENCES "customers" ("id")
);

CREATE TABLE "order_items" (
  "id" SERIAL PRIMARY KEY,
  "order_id" INTEGER NOT NULL,
  "product_id" INTEGER NOT NULL,
  "quantity" INTEGER NOT NULL,
  "unit_price" NUMERIC(10,2) NOT NULL,
  "total_price" NUMERIC(10,2) NOT NULL,
  FOREIGN KEY ("order_id") REFERENCES "orders" ("id"),
  FOREIGN KEY ("product_id") REFERENCES "products" ("id")
);

CREATE TABLE "reviews" (
  "id" SERIAL PRIMARY KEY,
  "product_id" INTEGER NOT NULL,
  "customer_id" INTEGER NOT NULL,
  "rating" INTEGER NOT NULL,
  "title" TEXT,
  "comment" TEXT,
  "is_verified_purchase" BOOLEAN NOT NULL DEFAULT FALSE,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY ("product_id") REFERENCES "products" ("id"),
  FOREIGN KEY ("customer_id") REFERENCES "customers" ("id")
);

CREATE TABLE "wishlist" (
  "customer_id" INTEGER NOT NULL,
  "product_id" INTEGER NOT NULL,
  PRIMARY KEY ("customer_id","product_id"),
  FOREIGN KEY ("customer_id") REFERENCES "customers" ("id"),
  FOREIGN KEY ("product_id") REFERENCES "products" ("id")
);

-- Data inserts (large dataset)

-- categories: 50 rows

-- customers: 2000 rows

-- products: 500 rows

-- orders: 3000 rows

-- order_items: 4000 rows

-- reviews: 350 rows

-- wishlist: 100 rows

SELECT setval(pg_get_serial_sequence('categories','id'), (SELECT COALESCE(MAX(id),1) FROM "categories"));
SELECT setval(pg_get_serial_sequence('customers','id'), (SELECT COALESCE(MAX(id),1) FROM "customers"));
SELECT setval(pg_get_serial_sequence('products','id'), (SELECT COALESCE(MAX(id),1) FROM "products"));
SELECT setval(pg_get_serial_sequence('orders','id'), (SELECT COALESCE(MAX(id),1) FROM "orders"));
SELECT setval(pg_get_serial_sequence('order_items','id'), (SELECT COALESCE(MAX(id),1) FROM "order_items"));
SELECT setval(pg_get_serial_sequence('reviews','id'), (SELECT COALESCE(MAX(id),1) FROM "reviews"));
